/*
 * jQuery gvChart plugin
 * Updated to support modern Google Charts loader (https://www.gstatic.com/charts/loader.js)
 * and jQuery 3+ compatibility.
 */
var googleLoaded = $.Deferred();

(function($) {
  var chartCounter = 0;

  function initGoogleCharts() {
    if (typeof google !== 'undefined' && google.charts) {
      google.charts.load('current', { packages: ['corechart', 'controls'] });
      google.charts.setOnLoadCallback(function() {
        $(function() {
          window.googleLoaded.resolve();
        });
      });
    } else {
      // Fallback if google.charts is not immediately defined
      setTimeout(initGoogleCharts, 50);
    }
  }

  initGoogleCharts();

  $.fn.gvChart = function(options) {
    return this.each(function() {
      var $table = $(this);
      var settings = {
        hideTable: true,
        chartType: 'AreaChart',
        chartDivID: 'gvChartDiv',
        gvSettings: {},
        swap: false
      };

      $.extend(settings, options);

      var chartDivId = settings.chartDivID + (chartCounter++);
      var $chartDiv = $('<div>').attr('id', chartDivId).addClass('gvChart').attr('aria-hidden', 'true');
      $table.before($chartDiv);

      if (settings.hideTable) {
        $table.hide();
        $table.attr('aria-hidden', 'false');
      }

      var dataTable = new google.visualization.DataTable();
      dataTable.addColumn('string', 'X labels');

      var $headers = $table.find('thead th');
      var $rows = $table.find('tbody tr');

      if (settings.swap) {
        $headers.each(function(index) {
          if (index) {
            dataTable.addColumn('number', $(this).text());
          }
        });
        dataTable.addRows($rows.length);
        $rows.each(function(rowIndex) {
          dataTable.setCell(rowIndex, 0, $(this).find('th').text());
          $(this).find('td').each(function(colIndex) {
            dataTable.setCell(rowIndex, colIndex + 1, parseFloat($(this).text(), 10));
          });
        });
      } else {
        $rows.each(function() {
          dataTable.addColumn('number', $(this).find('th').text());
        });
        dataTable.addRows($headers.length - 1);
        $headers.each(function(index) {
          if (index) {
            dataTable.setCell(index - 1, 0, $(this).text());
          }
        });
        $rows.each(function(rowIndex) {
          $(this).find('td').each(function(colIndex) {
            dataTable.setCell(colIndex, rowIndex + 1, parseFloat($(this).text(), 10));
          });
        });
      }

      if (!settings.gvSettings.title) {
        settings.gvSettings.title = $table.find('caption').text();
      }

      var chart = new google.visualization[settings.chartType](document.getElementById(chartDivId));
      chart.draw(dataTable, settings.gvSettings);
    });
  };
})(jQuery);
